// src/AppRouter.js
import { BrowserRouter, Routes, Route } from "react-router-dom";

// 🌐 públicas
import HomePage from "./HomePage";
import LoginPage from "./LoginPage";
import RegisterPage from "./RegisterPage";

// 👤 deportista
import BuscarClubesPage from "./BuscarClubesPage";
import CanchasPage from "./CanchasPage";           // 👈 IMPORTANTE
import MisReservasPage from "./MisReservasPage";
import NotificacionesPage from "./NotificacionesPage";
import PerfilPage from "./PerfilPage";

// Flujo de reserva / pago (ya los tenías)
import Reservas from "./components/navigation/Reservas";
import ConfirmarReservaPage from "./containers/pages/ConfirmarReservaPage";
import ProcesarPagoPage from "./containers/pages/ProcesarPagoPage";
import ReservaExitosaPage from "./containers/pages/ReservaExitosaPage";

export default function AppRouter() {
  return (
    <BrowserRouter>
      <Routes>
        {/* 🌐 PÚBLICAS */}
        <Route path="/" element={<HomePage />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/registrarse" element={<RegisterPage />} />

        {/* 👤 DEPORTISTA */}
        {/* búsqueda de clubes */}
        <Route path="/deportista/buscar" element={<BuscarClubesPage />} />

        {/* vista del club + selección de canchas
            Ejemplo: /deportista/club/2 */}
        <Route path="/deportista/club/:clubId" element={<CanchasPage />} />

        {/* historial de reservas */}
        <Route path="/deportista/reservas" element={<MisReservasPage />} />

        {/* notificaciones */}
        <Route
          path="/deportista/notificaciones"
          element={<NotificacionesPage />}
        />

        {/* perfil deportista */}
        <Route path="/deportista/perfil" element={<PerfilPage />} />

        {/* flujo de reserva y pago */}
        <Route path="/deportista/confirmar-reserva" element={<ConfirmarReservaPage />} />
        <Route path="/deportista/procesar-pago" element={<ProcesarPagoPage />} />
        <Route path="/deportista/reserva-exitosa" element={<ReservaExitosaPage />} />

        {/* ruta que ya tenías, la dejo viva por si la usas */}
        <Route path="/Reservas" element={<Reservas />} />
      </Routes>
    </BrowserRouter>
  );
}
